// Run against an isolated seeded local demo or a PR preview. Fictional users only.
// Usage: NODE_PATH=... CHROME_BIN=... node scripts/gallery-e2e.mjs <base> <screenshots>
import { createRequire } from 'node:module';
import { mkdirSync, readFileSync } from 'node:fs';
import assert from 'node:assert/strict';
const { chromium } = createRequire(import.meta.url)('playwright-core');
const base = process.argv[2], out = process.argv[3] ?? '/tmp/gallery-e2e'; mkdirSync(out,{recursive:true});
// Generated by theme-engine.generateTheme({primary:'#00695c',accent:'#4db6ac'}).
const theme = JSON.parse(readFileSync(new URL('./fixtures/gallery-teal-theme.json',import.meta.url),'utf8'));
const declarations = mode => Object.entries(theme[mode]).map(([k,v])=>k+':'+v+';').join('');
const teal = ':root{'+declarations('light')+'}:root[data-theme="dark"]{'+declarations('dark')+'}';
const browser = await chromium.launch({executablePath:process.env.CHROME_BIN,args:['--no-sandbox']});
const page = await browser.newPage({viewport:{width:1440,height:1050}}); page.setDefaultTimeout(20000);
page.on('dialog',d=>d.accept());
const errors=[];page.on('pageerror',e=>errors.push(e.message));
try {
  await page.goto(base+'/login',{waitUntil:'domcontentloaded'}); await page.locator('#signin-browser, [data-chain=password-only]').first().click();
  await page.fill('[name=username]','demo-alice'); await page.fill('[name=password]','demo-only-not-a-secret');
  await page.click('button[type=submit]'); await page.waitForSelector('[name=globalBranch]'); await page.locator('nav a[data-nav="/my-applications"]').click(); await page.waitForSelector('.lp-card');
  assert.ok(await page.locator('.lp-card').count()>=10);
  assert.equal(await page.getByText('Open with SSO',{exact:false}).count(),0);
  // Launching opens a new tab, never replaces the launchpad, and stays keyboard reachable.
  const launch = await page.locator('.lp-launch').evaluateAll(xs=>xs.map(x=>({target:x.getAttribute('target'),rel:x.getAttribute('rel'),tabIndex:x.tabIndex})));
  assert.ok(launch.length>=10);
  for (const l of launch) { assert.equal(l.target,'_blank'); assert.ok(l.rel.includes('noopener')); assert.ok(l.rel.includes('noreferrer')); assert.equal(l.tabIndex,0); }
  const popup = page.waitForEvent('popup',{timeout:5000}).catch(()=>null);
  await page.locator('.lp-launch').first().focus(); await page.keyboard.press('Enter');
  const tab = await popup; assert.ok(tab,'Enter on a launch link opens a popup tab');
  assert.equal(page.url().startsWith(base),true,'launchpad stays in the current tab'); await tab.close();
  await page.waitForSelector('.lp-card');
  await page.waitForFunction(()=>[...document.querySelectorAll('.lp-logo')].filter(x=>x.tagName==='IMG').every(x=>x.complete&&x.naturalWidth>0));
  const favourite=page.locator('[data-app=peoplehub] .lp-star');
  await favourite.click(); await page.waitForFunction(()=>document.querySelector('[aria-label=Favourites] [data-app=peoplehub]'));
  await page.reload(); await page.waitForSelector('[aria-label=Favourites] [data-app=peoplehub]');
  await page.fill('[name=applicationSearch]','no-such-application'); await page.getByText('No applications match your search.').waitFor();
  await page.fill('[name=applicationSearch]','');
  await page.screenshot({path:out+'/desktop-light.png',fullPage:true});
  await page.click('#lp-organise'); await page.waitForSelector('#lp-save'); assert.equal(await page.locator('.lp-launch').count(),0);
  const other=page.locator('[aria-label="Other applications"] .lp-card');
  const ids=await other.evaluateAll(xs=>xs.map(x=>x.dataset.app));
  await page.getByRole('button',{name:'Move '+await other.nth(1).locator('h3').textContent()+' up',exact:true}).click();
  await page.waitForFunction(id=>document.querySelector('[aria-label="Other applications"] .lp-card')?.dataset.app===id,ids[1]);
  await page.click('#lp-cancel'); await page.waitForSelector('#lp-organise'); assert.equal(await other.first().getAttribute('data-app'),ids[0]);
  await page.click('#lp-organise'); await page.waitForSelector('#lp-save');
  // Real pointer drag with capture, not a synthetic reorder call.
  const handle=other.nth(1).locator('.lp-handle'); const from=await handle.boundingBox(),to=await other.first().boundingBox();
  await page.mouse.move(from.x+from.width/2,from.y+from.height/2); await page.mouse.down(); await page.mouse.move(to.x+to.width/2,to.y+to.height/2,{steps:12}); await page.mouse.up();
  await page.waitForFunction(id=>document.querySelector('[aria-label="Other applications"] .lp-card')?.dataset.app===id,ids[1]);
  await page.screenshot({path:out+'/desktop-edit.png',fullPage:true});
  await page.click('#lp-save'); await page.waitForSelector('#lp-organise'); await page.reload(); await page.waitForSelector('.lp-card');
  await page.waitForFunction(id=>document.querySelector('[aria-label="Other applications"] .lp-card')?.dataset.app===id,ids[1]);
  await page.evaluate(()=>document.documentElement.dataset.theme='dark'); await page.screenshot({path:out+'/desktop-dark.png',fullPage:true});
  await page.setViewportSize({width:390,height:844}); await page.reload(); await page.waitForSelector('.lp-card'); await page.waitForFunction(()=>!document.querySelector('aside') || document.querySelector('aside').getBoundingClientRect().right<=0);
  await page.evaluate(()=>{document.documentElement.dataset.theme='light';});
  await page.screenshot({path:out+'/mobile-light.png',fullPage:true});
  assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);
  await page.click('#lp-organise'); await page.waitForSelector('#lp-save'); await page.screenshot({path:out+'/mobile-edit.png',fullPage:true});
  assert.equal(await page.locator('.lp-move button').first().evaluate(x=>x.getBoundingClientRect().height>=44),true);
  const mobileOther=page.locator('[aria-label="Other applications"] .lp-card');
  const mobileIds=await mobileOther.evaluateAll(xs=>xs.map(x=>x.dataset.app));
  await mobileOther.nth(1).locator('.lp-move button').nth(1).click();
  await page.waitForFunction(id=>document.querySelector('[aria-label="Other applications"] .lp-card')?.dataset.app===id,mobileIds[1]);
  // Touch drag on a real mobile viewport, using Chrome's input stack.
  await mobileOther.first().scrollIntoViewIfNeeded();
  const touchFrom=await mobileOther.first().locator('.lp-handle').boundingBox(), touchTo=await mobileOther.nth(1).boundingBox();
  const cdp=await page.context().newCDPSession(page); await cdp.send('Emulation.setTouchEmulationEnabled',{enabled:true,maxTouchPoints:1});
  const touch=async(type,x,y)=>cdp.send('Input.dispatchTouchEvent',{type,touchPoints:type==='touchEnd'?[]:[{x,y,id:1}]});
  await touch('touchStart',touchFrom.x+touchFrom.width/2,touchFrom.y+touchFrom.height/2);
  for(let n=1;n<=8;n++) await touch('touchMove',touchFrom.x+touchFrom.width/2+(touchTo.x+touchTo.width/2-touchFrom.x-touchFrom.width/2)*n/8,touchFrom.y+touchFrom.height/2+(touchTo.y+30-touchFrom.y-touchFrom.height/2)*n/8);
  await touch('touchEnd',0,0); await cdp.detach();
  await page.waitForFunction(id=>document.querySelector('[aria-label="Other applications"] .lp-card')?.dataset.app===id,mobileIds[0]);
  await page.click('#lp-cancel'); await page.waitForSelector('#lp-organise');
  await page.addStyleTag({content:teal}); await page.evaluate(()=>{document.documentElement.dataset.theme='dark';});
  await page.screenshot({path:out+'/mobile-dark-teal.png',fullPage:true});
  await page.setViewportSize({width:320,height:800}); assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);
  await page.screenshot({path:out+'/mobile-320.png',fullPage:true});
  // Admin artwork is staged on the selected branch, versioned in Dolt, and only live after Apply.
  await page.setViewportSize({width:1440,height:1050}); await page.reload(); await page.waitForSelector('.lp-card');
  await page.locator('nav a[data-nav="/applications"]').click(); await page.waitForSelector('#app-table');
  await page.locator('#app-table tr').filter({hasText:'PeopleHub'}).getByRole('button',{name:'Edit',exact:true}).click();
  await page.waitForSelector('.app-logo-preview');
  const before = await page.locator('.app-logo-preview').getAttribute('src');
  const artwork = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 40"><rect width="40" height="40" rx="10" fill="teal"/><path d="M8 20L17 29L32 10" fill="none" stroke="white" stroke-width="4"/></svg>';
  await page.locator('[name=alogo]').setInputFiles({name:'gallery-test.svg',mimeType:'image/svg+xml',buffer:Buffer.from(artwork)});
  await page.waitForFunction(old=>document.querySelector('.app-logo-preview')?.getAttribute('src')!==old,before);
  await page.screenshot({path:out+'/admin-logo.png',fullPage:true});
  await page.click('#app-save'); await page.getByText('Application saved.',{exact:false}).waitFor();
  await page.reload(); await page.waitForSelector('#app-table');
  await page.locator('#app-table tr').filter({hasText:'PeopleHub'}).getByRole('button',{name:'Edit',exact:true}).click();
  assert.notEqual(await page.locator('.app-logo-preview').getAttribute('src'),before);
  await page.click('#review-apply'); await page.waitForSelector('#workspace-apply'); await page.click('#workspace-apply');
  await page.waitForFunction(()=>document.body.textContent.includes('Applied personal/'));
  await page.locator('nav a[data-nav="/my-applications"]').click(); await page.waitForSelector('[data-app=peoplehub] img');
  const after=await page.locator('[data-app=peoplehub] img').getAttribute('src'); assert.notEqual(after,before);
  await page.waitForFunction(()=>document.querySelector('[data-app=peoplehub] img')?.naturalWidth>0);
  // A second authenticated user must not inherit Alice's favourites.
  await page.getByRole('button',{name:'Sign out',exact:true}).click();
  await page.locator('#signin-browser, [data-chain=password-only]').first().click();
  await page.fill('[name=username]','demo-bob'); await page.fill('[name=password]','demo-only-not-a-secret'); await page.click('button[type=submit]');
  await page.waitForSelector('.lp-card'); assert.equal(await page.locator('[aria-label=Favourites] .lp-card').count(),0);
  assert.equal(await page.locator('[data-app=peoplehub]').count(),0);
  assert.deepEqual(errors,[]);
  console.log('GALLERY E2E PASS: stars, reload persistence, search, cancel, move buttons, real drag, save, desktop/mobile, theme variations, admin upload + Apply and user isolation');
} catch(e) { await page.screenshot({path:out+'/failure.png',fullPage:true});throw e; }
finally { await browser.close(); }
